"""Deterministic lossless codec for generated byte-coverage glyph pages."""
from collections import defaultdict,deque

def encode(raw):
 raw=bytes(raw)
 table=defaultdict(lambda:deque(maxlen=32));out=bytearray();literal=bytearray();i=0
 def flush():
  while literal:
   n=min(128,len(literal));out.append(n-1);out.extend(literal[:n]);del literal[:n]
 while i<len(raw):
  best=offset=0
  if i+4<=len(raw):
   for pos in reversed(table[raw[i:i+4]]):
    length=4
    while length<131 and i+length<len(raw) and raw[pos+length]==raw[i+length]:length+=1
    if length>best:best=length;offset=i-pos
    if best==131:break
  step=best if best>=4 else 1
  if best>=4:flush();out.append(128|best-4);out.extend(offset.to_bytes(2,'little'))
  else:literal.append(raw[i])
  for pos in range(i,i+step):
   if pos+4<=len(raw):table[raw[pos:pos+4]].append(pos)
  i+=step
  if len(literal)==128:flush()
 flush();return bytes(out)

def decode(data,size,width,kind):
 out=bytearray();i=0
 while i<len(data):
  token=data[i];i+=1;count=(token&127)+(4 if token&128 else 1)
  if token&128:
   distance=int.from_bytes(data[i:i+2],'little');i+=2;assert 0<distance<=len(out)
   for _ in range(count):out.append(out[-distance])
  else:assert i+count<=len(data);out.extend(data[i:i+count]);i+=count
 assert i==len(data) and len(out)==size
 if kind:
  distance=width if kind in (1,3) else 1
  for i in range(len(out)):
   valid=i>=width if kind in (1,3) else i%width!=0
   if valid:out[i]=(out[i]+out[i-distance])&255 if kind<=2 else out[i]^out[i-distance]
 return bytes(out)

def pack(raw,width):
 choices=[]
 for kind in range(5):
  filtered=bytearray(raw)
  if kind:
   distance=width if kind in (1,3) else 1
   for i in range(len(raw)):
    valid=i>=width if kind in (1,3) else i%width!=0
    if valid:filtered[i]=(raw[i]-raw[i-distance])&255 if kind<=2 else raw[i]^raw[i-distance]
  packed=encode(filtered);assert decode(packed,len(raw),width,kind)==raw;choices.append((len(packed),kind,packed))
 _,kind,packed=min(choices);return kind,packed
